Object.assign(poses,{default:[standing,standing],squat:[standing,squat],wallsit:[wallsit(false),wallsit(true)],split:[split(false),split(true)],hinge:[standing,[[78,35],[65,42],[40,60],[67,60],[68,76],[61,61],[61,74],[47,77],[49,100],[40,78],[38,100]]],bridge:[lying(),lying(60)],bandbridge:[lying(),lying(60)],tilt:[lying(),lying(79)],deadbug:[lying(),[[16,75],[29,83],[52,83],[35,80],[48,77],[35,87],[50,88],[71,69],[77,100],[75,83],[94,99]]],bird:[bird(false),bird(true)],leg:[side(false,false),side(true,false)],side:[side(false,true),side(true,true)],wallpush:[push(false),push(true)],stretch:[stretch(false),stretch(true)],press:[press(false),press(true)],curl:[curl(false),curl(true)],row:[row(false),row(true)],bandrow:[row(false),row(true)],triceps:[row(false),row(true)],calf:[standing,standing.map(([x,y],i)=>[x,y-(i===8||i===10?0:4)])]});
const AR={squat:{steps:'قفي أمام كرسي ثابت. اثني الوركين والركبتين واجلسي بخفة، ثم قفي ببطء. استعيني بيديكِ إذا احتجتِ.'},bridge:{steps:'استلقي على ظهرك مع ثني الركبتين وقدميكِ على الأرض. ارفعي الحوض قليلًا براحة ثم اخفضيه ببطء.'},hinge:{steps:'قفي مع ثني بسيط للركبتين. حركي الوركين إلى الخلف قليلًا ثم عودي للوقوف. ابدئي بلا أوزان.'},row:{steps:'استندي بيد إلى سطح ثابت، وحركي الكوع الآخر للخلف بلطف ثم أعيديه. بدلي الجانبين.'},bandrow:{steps:'امسكي شريطًا خفيفًا بصورة آمنة، واسحبي الكوعين للخلف برفق ثم عودي ببطء. لا تستخدمي تثبيتًا غير آمن.'},deadbug:{steps:'استلقي مع ثني الركبتين. مرري كعبًا بعيدًا قليلًا على الأرض ثم أعيديه وبدلي.'},tilt:{steps:'استلقي مع ثني الركبتين. حركي الحوض برفق في نطاق صغير ومريح، ثم عودي للوضع المحايد.'},stretch:{steps:'قفي قرب دعم ثابت بإحدى القدمين أمام الأخرى. انقلي وزنك برفق حتى تشعري بتمدد بسيط، ثم بدلي.'},wallpush:{steps:'ضعي راحتيك على حائط ثابت بمستوى الصدر. اثني الكوعين قليلًا ثم ادفعي بعيدًا عن الحائط.'},press:{steps:'اجلسي على كرسي ثابت. ارفعي اليدين في نطاق مريح ثم اخفضيهما ببطء. ابدئي بلا أوزان.'},curl:{steps:'أبقي الكوعين قرب الجسم واثنيهما لرفع اليدين، ثم اخفضيهما ببطء.'},triceps:{steps:'اجلسي مع دعم مريح، وافردي الكوع واثنيه برفق في اتجاه مريح.'},side:{steps:'استلقي على جانبك والركبتان مثنيتان، والكوع تحت الكتف. ارفعي الحوض قليلًا إن كان مريحًا ثم اخفضيه.'},bird:{steps:'ابدئي على اليدين والركبتين. مرري قدمًا للخلف على الأرض ثم أعيديها وبدلي. حافظي على راحة الجذع.'},split:{steps:'قفي بخطوة قصيرة قرب دعم ثابت. اثني الركبتين قليلًا ثم عودي للوقوف وبدلي الجانبين.'},bandbridge:{steps:'اتخذي وضع الجسر العادي. يمكنكِ استخدام شريط خفيف فوق الركبتين إن كان مريحًا، أو الاستغناء عنه.'},leg:{steps:'استلقي على جانبك مع ثني الركبة السفلى للتوازن. ارفعي الساق العليا قليلًا ثم اخفضيها وبدلي.'},wallsit:{steps:'استندي بخفة إلى حائط ثابت. اثني الركبتين قليلًا واثبتي للحظات ثم قفي. لا داعي للنزول العميق.'},calf:{steps:'قفي بجوار حائط أو كرسي ثابت. ارفعي الكعبين برفق ثم اخفضيهما ببطء.'}};
function session(){let s=state.session;if(!s)return `<div class="empty">${T('لا توجد جلسة محفوظة.','No saved session.')}</div>${btn(T('الجدول','Schedule'),'go:work','primary wide')}`;let x=s.items[s.index];if(!x)return `<div class="stack">${title(T('انتهت الحركة','Movement finished'))}${btn(T('حفظ الجلسة','Save session'),'finish','primary wide')}</div>`;let e=E[x.id],done=s.logs.length,total=s.items.reduce((n,x)=>n+x.sets,0),rest=s.restUntil?Math.max(0,Math.ceil((s.restUntil-Date.now())/1000)):s.restRemaining||0;return `<div class="stack"><div class="active-header"><span class="eyebrow">${T('جلستك','YOUR SESSION')} · ${s.index+1}/${s.items.length}</span>${btn(T('إنهاء','Finish'),'end','plain')}</div><div class="progress"><i style="width:${Math.min(100,100*done/Math.max(1,total))}%"></i></div>${title(esc(name(e)),esc(e.equipment))}${demo(e.id)}<div class="row between"><span class="pill">${T('مبتدئة','Beginner')}</span>${btn(T('دليل الحركة','Form guide'),'detail:'+e.id,'plain')}</div>${card(`<div class="stack"><p class="muted">${esc(ar()?AR[e.id]?.steps||e.steps:e.steps)}</p><p class="tiny">${T('توقفي عند الألم أو الدوار.','Stop if you feel pain or dizziness.')}</p><div class="row between"><span class="eyebrow">${T('مجموعة اختيارية','OPTIONAL SET')} ${s.set+1}/${x.sets}</span>${pill(x.rest+'s '+T('راحة','rest'))}</div><div class="stepper">${btn('−','reps:-1','secondary')}<div style="text-align:center"><div class="number">${x.reps}</div><span class="tiny">${e.seconds?T('ثوانٍ','seconds'):T('تكرارات','reps')}</span></div>${btn('+','reps:1','secondary')}</div>${btn(T('تسجيل المجموعة','Log set'),'log','primary wide',s.paused||rest>0?'disabled':'')}${rest>0?`<div class="card" style="box-shadow:none;background:var(--bg)"><p class="muted" style="text-align:center">${T('وقت الراحة','Rest time')}</p><div id="timer" class="timer">${timerText(rest)}</div>${btn(T('تخطي المؤقت','Skip timer'),'skiprest','secondary wide')}</div>`:''}${s.paused?`<div class="notice">${T('الجلسة متوقفة ومحفوظة.','Session paused and saved.')}</div>`:''}</div>`)}<div class="work-controls">${btn(s.paused?T('متابعة','Continue'):T('إيقاف مؤقت','Pause'),'pause','secondary')}${btn(T('تخطي الحركة','Skip exercise'),'next','secondary')}${btn(T('السابق','Previous'),'prev','secondary',s.index===0?'disabled':'')}${btn(T('استبدال','Replace'),'replaceActive','secondary')}${btn(T('ملاحظة','Note'),'sessionNote','secondary')}${btn(T('حفظ وخروج','Save & leave'),'leave','secondary')}</div><p class="muted" style="text-align:center">${pet()} ${T('كل حركة مريحة تكفي. الراحة أيضًا اختيار جيد.','Any comfortable movement is enough. Rest is a good choice too.')}</p></div>`;}
function timerText(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function newSession(id){let p=plans.find(x=>x.id===id);if(!p||!routine(p).length){toast(T('الجدول فارغ','The routine is empty'));return;}if(state.session){modal(`<div class="stack">${title(T('لديكِ جلسة محفوظة','You have a saved session'))}${btn(T('متابعة المحفوظة','Resume saved session'),'resume','primary wide')}${btn(T('حفظ القديمة وبدء جديدة','Save old & start new'),'restart:'+id,'secondary wide')}</div>`);return;}state.session={id:crypto.randomUUID?.()||String(Date.now()),plan:id,items:structuredClone(routine(p)),index:0,set:0,logs:[],started:Date.now(),activeMs:0,runSince:Date.now(),paused:false,restUntil:0,restRemaining:0,note:''};save();close();go('active');syncWake();say(name(E[state.session.items[0].id]));}
function freeze(s){if(s.runSince){s.activeMs+=Math.max(0,Date.now()-s.runSince);s.runSince=0;}if(s.restUntil){s.restRemaining=Math.max(0,Math.ceil((s.restUntil-Date.now())/1000));s.restUntil=0;}s.paused=true;}
function unfreeze(s){s.paused=false;s.runSince=Date.now();if(s.restRemaining){s.restUntil=Date.now()+s.restRemaining*1000;s.restRemaining=0;}}
function moveIndex(s,dir){s.index=Math.min(s.items.length,Math.max(0,s.index+dir));s.set=0;s.restUntil=0;s.restRemaining=0;}
function finishSession(show=true){let s=state.session;if(!s)return;freeze(s);if(s.logs.length||s.note.trim()){state.history.push({id:s.id,date:today(),plan:s.plan,logs:s.logs,note:s.note,minutes:Math.max(1,Math.round(s.activeMs/60000)),partial:s.index<s.items.length});}dailyCredit();state.session=null;save();syncWake();close();if(show){go('home');let spark=state.reduce?'':Array.from({length:18},(_,i)=>`<i class="spark" style="left:${i*5.7}%;background:${(state.effects==='sparkle'?['#d1a657','#f1d990','#ffebc5']:['#d38da9','#c3a9e8','#e4c58b'])[i%3]};animation-delay:${i%5*.1}s"></i>`).join('');modal(`<div class="celebrate stack">${spark}<div class="flower">${pet()||'🌸'}</div><h1>${T('لحظة تستحق التقدير','A moment worth appreciating')}</h1><p class="muted">${T('شكرًا لأنك استمعتِ لجسمك. يمكنكِ الآن الراحة.','Thank you for listening to your body. Now you can rest.')}</p>${btn(T('تم','Done'),'close','primary wide')}</div>`);say(T('أحسنتِ الاهتمام بنفسك','Thank you for taking care of yourself'));}}
async function syncWake(){try{if(state.awake&&page==='active'&&state.session&&!state.session.paused&&'wakeLock'in navigator){if(!wakeLock||wakeLock.released)wakeLock=await navigator.wakeLock.request('screen');}else if(wakeLock){await wakeLock.release();wakeLock=null;}}catch{}}
const inspiration=[['flowers','Wedding','باقة من الفرح','A bouquet of joy','flowers','#e8b4c6','#fae7dc'],['dress','Wedding','ألوان الاحتفال','Celebration palette','dress','#d4bde1','#f7d9dc'],['ribbon','Style','تفاصيل ناعمة','Soft ribbon details','ribbon','#c3d3bb','#f7e7d2'],['moon','Self-care','مساء هادئ','A quiet evening','moon','#b7bce0','#f1dce8'],['mat','Movement','مساحة للحركة','A little room to move','mat','#d9bfac','#f5e4d7'],['tea','Self-care','صباح على مهلك','Slow morning','tea','#bcd1c2','#f8ead7'],['music','Movement','إيقاعك الخاص','Your own rhythm','music','#cbb5dc','#f3d6de'],['spark','Style','لمسة من البهجة','A touch of sparkle','spark','#e7cc96','#f9e5d8'],['book','Self-care','لحظة لنفسك','A moment for you','book','#edbbb7','#f6e7cc'],['garden','Self-care','نزهة في الحديقة','A garden walk','flowers','#b4cdb9','#efe3b9'],['palette','Wedding','ألوان مبهجة','Joyful colors','palette','#d5b7ce','#f5d7b5'],['rest','Movement','الراحة جزء من الرحلة','Rest belongs here','moon','#d1c5e9','#f6dfec']];
